import { useState } from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { MapPin, Mail, Phone, ArrowRight, ArrowUp } from "lucide-react";
import Logo from "../Accets/logo.png";
import { RevealSection, staggerContainer, staggerItem, MagneticButton } from "./motion/ScrollFX";

// lucide-react no longer ships brand/logo icons (Facebook, Instagram,
// LinkedIn, etc. were removed), so these are small self-contained SVGs
// with the same {size, className, style} API as a lucide icon component.
function FacebookIcon({ size = 24, className, style, ...rest }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" className={className} style={style} {...rest}>
      <path d="M22 12.06C22 6.5 17.52 2 12 2S2 6.5 2 12.06c0 5.02 3.66 9.18 8.44 9.94v-7.03H7.9v-2.91h2.54V9.85c0-2.5 1.49-3.89 3.77-3.89 1.1 0 2.24.2 2.24.2v2.46h-1.26c-1.24 0-1.63.77-1.63 1.56v1.88h2.78l-.44 2.91h-2.34v7.03C18.34 21.24 22 17.08 22 12.06Z" />
    </svg>
  );
}

function InstagramIcon({ size = 24, className, style, ...rest }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"
      className={className} style={style} {...rest}
    >
      <rect x="2" y="2" width="20" height="20" rx="5" />
      <circle cx="12" cy="12" r="4" />
      <circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none" />
    </svg>
  );
}

function LinkedinIcon({ size = 24, className, style, ...rest }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" className={className} style={style} {...rest}>
      <path d="M4.98 3.5a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5ZM3 9h4v12H3V9Zm7 0h3.6v1.7h.05c.5-.95 1.75-1.95 3.6-1.95 3.85 0 4.55 2.5 4.55 5.75V21h-4v-5.5c0-1.3-.02-3-1.85-3-1.85 0-2.15 1.4-2.15 2.9V21h-4V9Z" />
    </svg>
  );
}

// Social icon buttons, each in its own brand color. Hover state is
// tracked in React (not a CSS class) because the icon's inline
// `style={{ color }}` would otherwise always beat a `group-hover`
// utility class on specificity.
function SocialIcons({ links }) {
  const [hovered, setHovered] = useState(null);

  return (
    <div className="flex items-center gap-2.5">
      {links.map(({ href, label, Icon, color, background, hoverBackground }) => {
        const isHovered = hovered === label;
        return (
          <a
            key={label}
            href={href}
            target="_blank"
            rel="noopener noreferrer"
            data-cursor="hover"
            aria-label={label}
            onMouseEnter={() => setHovered(label)}
            onMouseLeave={() => setHovered(null)}
            className="h-9 w-9 rounded-full flex items-center justify-center transition-all duration-200"
            style={{ background: isHovered ? hoverBackground || color : background }}
          >
            <Icon
              size={16}
              style={{ color: isHovered ? "#FFFFFF" : color }}
              className="transition-colors duration-200"
            />
          </a>
        );
      })}
    </div>
  );
}

