// Small reusable link row with an arrow that slides in on hover —
// gives the columns some life instead of static text stacks.
function FooterLink({ to, label }) {
  return (
    <Link
      to={to}
      data-cursor="hover"
      style={{ color: theme.textMuted }}
      className="group flex items-center gap-1.5 hover:text-white transition-colors w-fit"
    >
      <span>{label}</span>
      <ArrowRight
        size={13}
        className="opacity-0 -translate-x-1 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-200"
        style={{ color: theme.accent }}
      />
    </Link>
  );
}

